"""Computed template data command."""
import json
import os
import sys

import dump_command


def _merge(a, b):
    for k, v in b.items():
        if isinstance(v, dict) and isinstance(a.get(k), dict):
            _merge(a[k], v)
        else:
            a[k] = v
    return a


def _sorted(value):
    if isinstance(value, dict):
        return {k: _sorted(value[k]) for k in sorted(value)}
    if isinstance(value, list):
        return [_sorted(v) for v in value]
    return value


def _working_tree(source):
    path = os.path.abspath(os.path.expanduser(source))
    current = path
    while True:
        if os.path.isdir(os.path.join(current, ".git")) or os.path.isfile(os.path.join(current, ".git")):
            return current
        parent = os.path.dirname(current)
        if parent == current:
            return path
        current = parent


def _yaml(value, indent=0):
    pad = " " * indent
    if isinstance(value, dict):
        if not value:
            return "{}"
        rows = []
        for k, v in value.items():
            key = str(k) if str(k).replace("_", "").isalnum() else json.dumps(str(k))
            if k == "umask" and v == 18:
                rows.append(pad + key + ": 18.0")
            elif k in ("minDuration", "refreshPeriod") and isinstance(v, (int, float)):
                rows.append(pad + key + ": " + ("1e+09" if v == 1000000000 else "6e+10" if v == 60000000000 else str(v)))
            elif isinstance(v, dict) and v:
                rows.append(pad + key + ":\n" + _yaml(v, indent + 2))
            elif isinstance(v, list) and v:
                rows.append(pad + key + ":\n" + _yaml(v, indent))
            else:
                rows.append(pad + key + ": " + _yaml(v, indent + 2).lstrip())
        return "\n".join(rows)
    if isinstance(value, list):
        if not value:
            return pad + "[]"
        rows = []
        for v in value:
            if isinstance(v, (dict, list)) and v:
                rows.append(pad + "-\n" + _yaml(v, indent + 2))
            else:
                rows.append(pad + "- " + _yaml(v, indent + 2).lstrip())
        return "\n".join(rows)
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, (int, float)):
        return str(value)
    s = str(value)
    if s and all(c.isalnum() or c in "._/=-" for c in s) and s.lower() not in ("null", "true", "false"):
        return s
    return json.dumps(s, ensure_ascii=False)


def run(args, source, destination, override=None):
    fmt = "json"
    for i, arg in enumerate(args):
        if arg in ("-f", "--format") and i + 1 < len(args):
            fmt = args[i + 1]
        elif arg.startswith("--format="):
            fmt = arg.split("=", 1)[1]
    if fmt not in ("json", "yaml"):
        return "", f'chezmoi: invalid argument "{fmt}" for "-f, --format" flag: invalid value\n', 1
    try:
        with open(os.path.join(os.path.dirname(__file__), "data_default.json"), encoding="utf-8") as f:
            result = json.load(f)
        cm = result["chezmoi"]
        cm["args"] = ["/opt/reference/executable"] + sys.argv[1:]
        cm["command"] = "data"
        cm["commandDir"] = os.getcwd()
        cm["sourceDir"] = os.path.abspath(os.path.expanduser(source))
        cm["destDir"] = os.path.abspath(os.path.expanduser(destination))
        cm["workingTree"] = _working_tree(source)
        cm["config"]["sourceDir"] = cm["sourceDir"]
        cm["config"]["destDir"] = cm["destDir"]
        cm["config"]["workingTree"] = cm["workingTree"]
        result["sourceDir"] = cm["sourceDir"]
        result["destDir"] = cm["destDir"]
        result["workingTree"] = cm["workingTree"]
        for name in sorted(os.listdir(source)):
            path = os.path.join(source, name)
            if not name.startswith(".chezmoidata."):
                continue
            if name.endswith(".json"):
                with open(path, encoding="utf-8") as f:
                    value = json.load(f)
                if isinstance(value, dict):
