"""Source-state serialization used by the dump command."""
import json
import os
import re
import stat


def decode_name(path):
    """Translate chezmoi source naming attributes into a target relative path."""
    parts = path.replace("\\", "/").split("/")
    out = []
    for part in parts:
        if part == ".chezmoiremove":
            continue
        if part.startswith("symlink_"):
            part = part[len("symlink_"):]
        for prefix in ("private_", "readonly_", "executable_"):
            if part.startswith(prefix):
                part = part[len(prefix):]
                break
        if part.startswith("dot_"):
            part = "." + part[4:]
        if part.endswith(".tmpl"):
            part = part[:-5]
        out.append(part)
    return "/".join(out)


def _render(text, data):
    # Cover the common Go-template constructs used for dotfile templates.
    def lookup(expr):
        expr = expr.strip()
        if expr.startswith("."):
            value = data
            for key in expr[1:].split("."):
                if not key:
                    continue
                if isinstance(value, dict) and key in value:
                    value = value[key]
                else:
                    return None, False
            return value, True
        if expr in ("true", "false"):
            return expr == "true", True
        if expr in ("nil", "null"):
            return None, True
        if re.fullmatch(r"-?\d+", expr):
            return int(expr), True
        if re.fullmatch(r"-?\d+\.\d+", expr):
            return float(expr), True
        if len(expr) >= 2 and expr[0] == expr[-1] and expr[0] in ('"', "'"):
            return expr[1:-1], True
        return expr, True

    # Simple conditionals, including an optional else branch.
    block = re.compile(r"{{\s*if\s+([^{}]+?)\s*}}(.*?){{\s*end\s*}}", re.S)
    while True:
        match = block.search(text)
        if not match:
            break
        condition, body = match.group(1), match.group(2)
        value, found = lookup(condition)
        yes, no = body, ""
        split = re.search(r"{{\s*else\s*}}", body)
        if split:
            yes, no = body[:split.start()], body[split.end():]
        truth = found and value not in (None, False, "", 0, [], {})
        text = text[:match.start()] + _render(yes if truth else no, data) + text[match.end():]

    def stringify(value):
        if isinstance(value, bool):
            return str(value).lower()
        if value is None:
            return "<no value>"
        return str(value)

    def sub(match):
        action = match.group(1).strip()
        bits = [part.strip() for part in action.split("|")]
        expr = bits[0]
        # Go's printf takes the format before the value.
        printf = re.fullmatch(r'printf\s+"((?:[^"\\]|\\.)*)"\s+(.+)', expr)
        if printf:
            value, found = lookup(printf.group(2))
            if not found:
                return match.group(0)
            fmt = printf.group(1)
            try:
                result = fmt.replace("%s", stringify(value)).replace("%v", stringify(value))
            except Exception:
                result = stringify(value)
        else:
            value, found = lookup(expr)
            if not found:
                return match.group(0)
            result = value
        for fn in bits[1:]:
            call = re.fullmatch(r"([A-Za-z][A-Za-z0-9_]*)\s+(.+)", fn)
            if call:
                name, arg_expr = call.groups()
                arg, arg_found = lookup(arg_expr)
                if not arg_found:
                    return match.group(0)
                try:
                    if name in ("add", "add1"):
                        result = result + (1 if name == "add1" else arg)
                    elif name in ("sub", "subtract"):
                        result = result - arg
                    elif name in ("mul", "multiply"):
                        result = result * arg
                    elif name in ("div", "divide"):
                        result = result / arg
                    elif name == "mod":
                        result = result % arg
                    elif name in ("max", "min"):
                        result = max(result, arg) if name == "max" else min(result, arg)
                    elif name == "trimPrefix":
                        result = stringify(result).removeprefix(stringify(arg))
                    elif name == "trimSuffix":
                        result = stringify(result).removesuffix(stringify(arg))
                    else:
                        return match.group(0)
                except (TypeError, ValueError, ZeroDivisionError):
                    return match.group(0)
                continue
            if fn == "upper":
                result = stringify(result).upper()
            elif fn == "lower":
                result = stringify(result).lower()
            elif fn == "title":
                result = stringify(result).title()
            elif fn in ("trim", "trimSpace"):
                result = stringify(result).strip()
            elif fn in ("toJson", "json"):
                result = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
            elif fn == "quote":
