def _yaml(obj):
    # Small deterministic YAML emitter for the scalar/map structures in dumps.
    def scalar(v):
        if isinstance(v, int):
            return str(v)
        if "\n" in v and v.endswith("\n") and "\\" not in v:
            body = "".join("    " + line for line in v.splitlines(True))
            return "|\n" + body
        if v and all(c.isalnum() or c in "._/-" for c in v) and v.lower() not in ("null", "true", "false"):
            return v
        return json.dumps(v, ensure_ascii=False)
    lines = []
    for name, entry in obj.items():
        lines.append(f"{scalar(name)}:")
        for key, value in entry.items():
            if isinstance(value, str) and "\n" in value and value.endswith("\n") and "\\" not in value:
                lines.append(f"  {key}: |")
                lines.extend("    " + l for l in value[:-1].split("\n"))
            else:
                lines.append(f"  {key}: {scalar(value)}")
    return "\n".join(lines) + ("\n" if lines else "{}\n")

