def _encode(rel, mode, is_link=False, exact=False):
    parts = rel.split(os.sep)
    out = []
    for part in parts:
        if part.startswith('.'):
            part = 'dot_' + part[1:]
        out.append(part)
    name = os.path.join(*out)
    if exact:
        name = 'exact_' + name
    else:
        prefix = ''
        if is_link:
            prefix = 'symlink_'
        elif mode & 0o111:
            prefix = 'executable_'
        elif (mode & 0o077) == 0:
            prefix = 'private_'
        elif not mode & 0o222:
            prefix = 'readonly_'
        if prefix:
            out[-1] = prefix + out[-1]
            name = os.path.join(*out)
    return name


